package com.gameaggregator.billingservice.domain;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;@Entity @Table(name="credit_notes") public class CreditNote{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID invoiceId;@Column(nullable=false,precision=19,scale=6)public BigDecimal amount;@Column(nullable=false)public String reason;@Column(nullable=false)public Instant createdAt=Instant.now();protected CreditNote(){}public CreditNote(UUID i,BigDecimal a,String r){invoiceId=i;amount=a;reason=r;}}